import XCTest
final class ProbeTests:XCTestCase {
 func testFormalNativeColdReadonlyAfterWebAndNativeHostsDissolve() throws {
  continueAfterFailure=false
  let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:5){decline.tap()};app.buttons["Inbox, tab, 4 of 5"].tap()
  let guest=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA Native Cancellation Table")).firstMatch;XCTAssertTrue(guest.waitForExistence(timeout:10));guest.tap();XCTAssertTrue(app.staticTexts["History is read-only."].firstMatch.waitForExistence(timeout:10));XCTAssertTrue(app.staticTexts["QA native confirmed cancellation."].firstMatch.exists);XCTAssertTrue(app.staticTexts["QA Web after native rejoin."].firstMatch.exists);XCTAssertFalse(app.staticTexts["QA Web absence gap for native."].firstMatch.exists);XCTAssertFalse(app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch.exists);XCTAssertFalse(app.buttons["Dissolve group"].exists);XCTAssertFalse(app.buttons["Leave group"].exists);print("QA_NATIVE_GUEST_DISSOLVED_UNION\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native-guest-dissolved-union-readonly";a.lifetime = .keepAlways;add(a)
  app.navigationBars.buttons["Back"].tap();app.buttons["Inbox, tab, 4 of 5"].tap();print("QA_NATIVE_COLD_INBOX_AFTER_RETURN\n"+app.debugDescription);let host=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA Native Reverse Table")).firstMatch;XCTAssertTrue(host.waitForExistence(timeout:8),app.debugDescription);host.tap();XCTAssertTrue(app.staticTexts["History is read-only."].firstMatch.waitForExistence(timeout:10));XCTAssertTrue(app.staticTexts["QA after rejoin visible."].firstMatch.exists);XCTAssertFalse(app.textViews.matching(NSPredicate(format:"label BEGINSWITH %@","Message")).firstMatch.exists);XCTAssertFalse(app.buttons["Dissolve group"].exists);XCTAssertFalse(app.buttons["Leave group"].exists);print("QA_NATIVE_HOST_COLD_DISSOLVED_NO_REOPEN\n"+app.debugDescription);let b=XCTAttachment(screenshot:app.screenshot());b.name="native-host-cold-dissolved-readonly";b.lifetime = .keepAlways;add(b)
 }
}
